#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sky:bus_read.glsl>
#include <sky:atmosphere.glsl>

// Exposure for the sky, into a 1 x 1 target: the average sky luminance over a few directions sets how
// bright the sky is drawn, like a camera's automatic exposure. Bounded, so the night stays dark.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    SkyBus bus = sky_read_bus(InSampler);
    float exposure = 1.0;
    if (bus.present) {
        float altitude = sky_altitude(float(CameraBlockPos.y) - CameraOffset.y);
        vec3 sum = vec3(0.0);
        vec3 unused;
        sum += sky_sky(vec3(0.0, 1.0, 0.0), bus.sunDirection, bus.rainBrightness, altitude, unused);
        for (int i = 0; i < 4; i++) {
            float a = float(i) * 0.5 * SKY_PI;
            sum += sky_sky(normalize(vec3(cos(a), 0.25, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
            sum += sky_sky(normalize(vec3(cos(a), 1.0, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
        }
        float luminance = dot(sum / 9.0, vec3(0.2126, 0.7152, 0.0722));
        exposure = clamp(SKY_EXPOSURE_KEY / max(luminance, 1e-6), SKY_EXPOSURE_MIN, SKY_EXPOSURE_MAX);
    }
    fragColor = sky_pack_float(exposure);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#ifndef SKY_ATMOSPHERE_GLSL
#define SKY_ATMOSPHERE_GLSL

// Sky from single scattering in an Earth-like atmosphere: Rayleigh scattering (air molecules, the blue
// sky), Mie scattering (aerosols, the glow around the sun) and ozone absorption (the deep blue of
// twilight). Ray-marched per pixel, in meters, with the planet's center below the camera.
// Coefficients: Bruneton & Neyret 2008, Hillaire 2020.

#define SKY_VIEW_STEPS 16
#define SKY_LIGHT_STEPS 4

const float SKY_PI = 3.14159265;
const float SKY_PLANET_RADIUS = 6360e3;
const float SKY_ATMOSPHERE_RADIUS = 6460e3;
const vec3 SKY_RAYLEIGH_SCATTERING = vec3(5.802e-6, 13.558e-6, 33.1e-6);
const float SKY_MIE_SCATTERING = 3.996e-6;
const float SKY_MIE_EXTINCTION = 4.440e-6;
const float SKY_MIE_G = 0.8;
const vec3 SKY_OZONE_ABSORPTION = vec3(0.650e-6, 1.881e-6, 0.085e-6);

const vec3 SKY_SUN_RADIANCE = vec3(20.0);
const vec3 SKY_MOON_RADIANCE = vec3(0.020, 0.024, 0.032);   // dimmer and slightly blue: night vision
const vec3 SKY_NIGHT_GLOW = vec3(0.0006, 0.0008, 0.0016);   // airglow and starlight, so night is never black
// Automatic exposure (post/exposure): exposure = key / average sky luminance, within these bounds.
const float SKY_EXPOSURE_KEY = 0.28;
const float SKY_EXPOSURE_MIN = 0.05;
const float SKY_EXPOSURE_MAX = 30.0;
// Distance, in blocks, over which the haze of the air covers about 63% of what is behind it.
const float SKY_HAZE_DISTANCE = 900.0;

// Translucent pixels above this height are clouds (the overworld's cloud_height is 192.33).
const float SKY_CLOUD_BOTTOM = 190.0;

const float SKY_SUN_COS_RADIUS = 0.99985;                    // about 1 degree: bigger than the real sun, reads better

// Density of air, aerosols and ozone at height h, relative to sea level.
vec3 sky_density(float h) {
    return vec3(exp(-h / 8000.0), exp(-h / 1200.0), max(0.0, 1.0 - abs(h - 25000.0) / 15000.0));
}

vec3 sky_extinction(vec3 opticalDepth) {
    return SKY_RAYLEIGH_SCATTERING * opticalDepth.x + SKY_MIE_EXTINCTION * opticalDepth.y + SKY_OZONE_ABSORPTION * opticalDepth.z;
}

// Distance from o (inside the sphere) to where the ray leaves the sphere of radius r centered on the origin.
float sky_sphere_exit(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    return -b + sqrt(max(b * b - c, 0.0));
}

// Distance to where the ray enters the sphere from outside, or -1.
float sky_sphere_entry(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    float h = b * b - c;
    if (h < 0.0) {
        return -1.0;
    }
    return -b - sqrt(h);
}

// Fraction of light that reaches p from direction l, through the rest of the atmosphere.
vec3 sky_transmittance_to_light(vec3 p, vec3 l) {
    if (sky_sphere_entry(p, l, SKY_PLANET_RADIUS) > 0.0) {
        return vec3(0.0);   // behind the planet
    }
    float dt = sky_sphere_exit(p, l, SKY_ATMOSPHERE_RADIUS) / float(SKY_LIGHT_STEPS);
    vec3 depth = vec3(0.0);
    for (int i = 0; i < SKY_LIGHT_STEPS; i++) {
        depth += sky_density(length(p + l * ((float(i) + 0.5) * dt)) - SKY_PLANET_RADIUS) * dt;
    }
    return exp(-sky_extinction(depth));
}

// Light scattered toward the camera along direction d, from a light in direction l with radiance 1.
// transmittance: how much of what is behind the atmosphere along d gets through (for the sun disc).
vec3 sky_scattering(vec3 d, vec3 l, float altitude, out vec3 transmittance) {
    vec3 o = vec3(0.0, SKY_PLANET_RADIUS + altitude, 0.0);
    float rayLength = sky_sphere_exit(o, d, SKY_ATMOSPHERE_RADIUS);
    float mu = dot(d, l);
    float phaseRayleigh = 3.0 / (16.0 * SKY_PI) * (1.0 + mu * mu);
    float g2 = SKY_MIE_G * SKY_MIE_G;
    float phaseMie = 3.0 / (8.0 * SKY_PI) * (1.0 - g2) * (1.0 + mu * mu)
                   / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * SKY_MIE_G * mu, 1.5));
    vec3 depth = vec3(0.0);
    vec3 sum = vec3(0.0);
    // Steps grow quadratically: dense air near the camera gets most of them.
    for (int i = 0; i < SKY_VIEW_STEPS; i++) {
        float t0 = rayLength * pow(float(i) / float(SKY_VIEW_STEPS), 2.0);
        float t1 = rayLength * pow(float(i + 1) / float(SKY_VIEW_STEPS), 2.0);
        float dt = t1 - t0;
        vec3 p = o + d * (0.5 * (t0 + t1));
        vec3 density = sky_density(length(p) - SKY_PLANET_RADIUS);
        vec3 toCamera = exp(-sky_extinction(depth + density * (0.5 * dt)));
        vec3 scatter = SKY_RAYLEIGH_SCATTERING * density.x * phaseRayleigh + SKY_MIE_SCATTERING * density.y * phaseMie;
        sum += toCamera * sky_transmittance_to_light(p, l) * scatter * dt;
        depth += density * dt;
    }
    transmittance = exp(-sky_extinction(depth));
    return sum;
}

// Linear radiance of the sky in world direction dir, without the sun disc. The ground below the horizon
// is not modeled: directions below it look at the horizon, darkened.
vec3 sky_sky(vec3 dir, vec3 sunDirection, float rainBrightness, float altitude, out vec3 transmittance) {
    vec3 d = normalize(vec3(dir.x, max(dir.y, 0.0), dir.z));
    vec3 color = SKY_NIGHT_GLOW;
    transmittance = vec3(1.0);
    if (sunDirection.y > -0.3) {
        color += sky_scattering(d, sunDirection, altitude, transmittance) * SKY_SUN_RADIANCE;
    }
    if (-sunDirection.y > -0.3) {
        vec3 unused;
        color += sky_scattering(d, -sunDirection, altitude, unused) * SKY_MOON_RADIANCE;
    }
    color *= mix(1.0, 0.25, smoothstep(0.0, -0.3, dir.y));
    // Rain: a grey, darker overcast sky.
    float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
    return mix(color, vec3(luminance * 0.45), (1.0 - rainBrightness) * 0.9);
}

// Linear radiance of the sun disc in direction dir, seen through the atmosphere.
vec3 sky_sun_disc(vec3 dir, vec3 sunDirection, vec3 transmittance, float rainBrightness) {
    float c = dot(dir, sunDirection);
    if (c < SKY_SUN_COS_RADIUS - 0.0001 || dir.y < 0.0) {
        return vec3(0.0);
    }
    float edge = smoothstep(SKY_SUN_COS_RADIUS - 0.0001, SKY_SUN_COS_RADIUS + 0.00002, c);
    // Limb darkening: the edge of the disc is dimmer than its center.
    float r = sqrt(clamp((1.0 - c) / (1.0 - SKY_SUN_COS_RADIUS), 0.0, 1.0));
    float limb = 0.4 + 0.6 * sqrt(1.0 - r * r);
    return SKY_SUN_RADIANCE * 40.0 * transmittance * edge * limb * rainBrightness * rainBrightness;
}

// Height of the camera above the sea, in meters, from its block height: the overworld sea is at y = 63.
float sky_altitude(float cameraY) {
    return clamp(200.0 + (cameraY - 63.0) * 2.0, 20.0, 4000.0);
}

// ACES filmic curve (Narkowicz 2015), then sRGB-like gamma.
vec3 sky_tonemap(vec3 linear) {
    vec3 x = linear;
    vec3 mapped = clamp(x * (2.51 * x + 0.03) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
    return pow(mapped, vec3(1.0 / 2.2));
}

#endif

#ifndef SKY_BUS_GLSL
#define SKY_BUS_GLSL

// Data bus.
//
// Column x = 0 of the screen carries values from core shaders to the post effects. Every program that
// draws the world discards its fragments in that column (SKY_PROTECT_BUS), and the writers relocate
// their geometry onto a strip of it. The post effects read the values, then paint the column over.
//
// Rows, numbered from NDC y = -1 (the bottom of the screen):
#define SKY_ROW_MARKER 0      // magenta: the bus was written this frame
#define SKY_ROW_PROJ 1        // ProjMat, 16 floats, column-major
#define SKY_ROW_VIEW 17       // view rotation (the sky's ModelViewMat), 16 floats, column-major
#define SKY_ROW_SKY 33        // sky color (ColorModulator of the sky disc), 3 channels
#define SKY_ROW_FOG 34        // FogColor
#define SKY_ROW_FOG_PARAMS 35 // 6 floats: FogEnvironmentalStart, FogEnvironmentalEnd, FogRenderDistanceStart,
                             // FogRenderDistanceEnd, FogSkyEnd, FogCloudsEnd
#define SKY_SKY_ROWS 41       // rows written by the sky
#define SKY_ROW_SUN 41        // view-space sun direction (3 components), then the rain brightness mapped to [-1, 1]:
#define SKY_SUN_ROWS 4        // 24-bit fixed point each
// The sun is drawn with additive blending (color = src * alpha + dst), after the sky: the sky clears the
// sun's rows to black first, so the sum is exactly what the sun writes.
#define SKY_SKY_STRIP_ROWS 45 // rows covered by the sky's strip: its own values, then the cleared sun rows

// Discard fragments that would land on the bus column. Orthographic renders (the GUI, and the GUI item
// atlas, which core/item draws into) are left alone: they happen elsewhere or after the post effects.
// Needs ProjMat (#include <minecraft:projection.glsl>).
#define SKY_PROTECT_BUS if (gl_FragCoord.x < 1.0 && ProjMat[2][3] != 0.0) { discard; }
// For full-screen copies onto the world (blit_screen), which have no ProjMat.
#define SKY_PROTECT_BUS_ALWAYS if (gl_FragCoord.x < 1.0) { discard; }

// A float as 4 bytes (RGBA). Only for writers without blending: the alpha channel is part of the value.
vec4 sky_pack_float(float v) {
    uint b = floatBitsToUint(v);
    return vec4(float((b >> 24u) & 255u), float((b >> 16u) & 255u), float((b >> 8u) & 255u), float(b & 255u)) / 255.0;
}

float sky_unpack_float(vec4 c) {
    uvec4 b = uvec4(round(c * 255.0));
    return uintBitsToFloat((b.x << 24u) | (b.y << 16u) | (b.z << 8u) | b.w);
}

// A value in [-1, 1] as 24-bit fixed point in RGB, alpha 1: safe for writers with alpha blending.
vec4 sky_pack_signed(float v) {
    uint q = uint(round(clamp(v * 0.5 + 0.5, 0.0, 1.0) * 16777215.0));
    return vec4(float((q >> 16u) & 255u), float((q >> 8u) & 255u), float(q & 255u), 255.0) / 255.0;
}

float sky_unpack_signed(vec4 c) {
    uvec3 b = uvec3(round(c.rgb * 255.0));
    return float((b.x << 16u) | (b.y << 8u) | b.z) / 16777215.0 * 2.0 - 1.0;
}

// Clip-space position of a corner of the strip covering bus rows [firstRow, firstRow + rows).
// corner is (0 or 1, 0 or 1). Corners (0,0), (1,0), (1,1), (0,1) in that order are front-facing.
vec4 sky_strip_corner(vec2 corner, int firstRow, int rows, vec2 screenSize) {
    vec2 pixel = vec2(corner.x, float(firstRow) + corner.y * float(rows));
    return vec4(-1.0 + 2.0 * pixel / screenSize, 0.0, 1.0);
}

#endif

#ifndef SKY_BUS_READ_GLSL
#define SKY_BUS_READ_GLSL

#include <sky:bus.glsl>

// Reading the data bus in a post effect, from an input bound to minecraft:main.

struct SkyBus {
    bool present;
    mat4 proj;
    mat4 invProj;
    mat3 viewToWorld;     // camera-relative world axes from view space (the inverse of the view rotation)
    bool zZeroToOne;      // depth range of the backend: [0, 1] (Vulkan) or [-1, 1] (OpenGL without clip control)
    vec3 skyColor;
    vec3 fogColor;        // also the color the frame was cleared to
    float fogEnvironmentalStart;
    float fogEnvironmentalEnd;
    float fogRenderDistanceStart;
    float fogRenderDistanceEnd;
    float fogSkyEnd;
    float fogCloudsEnd;
    vec3 sunDirection;    // world space
    float rainBrightness; // 1: clear, 0: full rain
};

vec4 sky_bus_texel(sampler2D bus, int row, bool fromBottom) {
    int height = textureSize(bus, 0).y;
    return texelFetch(bus, ivec2(0, fromBottom ? row : height - 1 - row), 0);
}

bool sky_is_marker(vec4 c) {
    return all(lessThan(abs(c.rgb - vec3(1.0, 0.0, 1.0)), vec3(0.01)));
}

SkyBus sky_read_bus(sampler2D bus) {
    SkyBus b;
    // Texel row 0 is the bottom of the screen on both backends; the top row is checked too, just in case.
    bool fromBottom = sky_is_marker(texelFetch(bus, ivec2(0, 0), 0));
    b.present = fromBottom || sky_is_marker(texelFetch(bus, ivec2(0, textureSize(bus, 0).y - 1), 0));
    if (!b.present) {
        return b;
    }
    mat4 view;
    for (int i = 0; i < 16; i++) {
        b.proj[i / 4][i % 4] = sky_unpack_float(sky_bus_texel(bus, SKY_ROW_PROJ + i, fromBottom));
        view[i / 4][i % 4] = sky_unpack_float(sky_bus_texel(bus, SKY_ROW_VIEW + i, fromBottom));
    }
    b.invProj = inverse(b.proj);
    b.viewToWorld = transpose(mat3(view));
    // Reversed depth (near 1, far 0) with JOML's perspective: proj[2][2] = near / (far - near) for a [0, 1]
    // depth range, (far + near) / (far - near) for [-1, 1].
    b.zZeroToOne = b.proj[2][2] < 0.5;
    b.skyColor = sky_bus_texel(bus, SKY_ROW_SKY, fromBottom).rgb;
    b.fogColor = sky_bus_texel(bus, SKY_ROW_FOG, fromBottom).rgb;
    float fog[6];
    for (int i = 0; i < 6; i++) {
        fog[i] = sky_unpack_float(sky_bus_texel(bus, SKY_ROW_FOG_PARAMS + i, fromBottom));
    }
    b.fogEnvironmentalStart = fog[0];
    b.fogEnvironmentalEnd = fog[1];
    b.fogRenderDistanceStart = fog[2];
    b.fogRenderDistanceEnd = fog[3];
    b.fogSkyEnd = fog[4];
    b.fogCloudsEnd = fog[5];
    vec3 sunView = vec3(sky_unpack_signed(sky_bus_texel(bus, SKY_ROW_SUN, fromBottom)),
                        sky_unpack_signed(sky_bus_texel(bus, SKY_ROW_SUN + 1, fromBottom)),
                        sky_unpack_signed(sky_bus_texel(bus, SKY_ROW_SUN + 2, fromBottom)));
    b.sunDirection = normalize(b.viewToWorld * sunView);
    b.rainBrightness = sky_unpack_signed(sky_bus_texel(bus, SKY_ROW_SUN + 3, fromBottom)) * 0.5 + 0.5;
    return b;
}

// Camera-relative position, in view space, of the point at this screen position and depth.
vec3 sky_view_position(SkyBus b, vec2 texCoord, float depth) {
    float z = b.zZeroToOne ? depth : depth * 2.0 - 1.0;
    vec4 p = b.invProj * vec4(texCoord * 2.0 - 1.0, z, 1.0);
    return p.xyz / p.w;
}

// Whether the camera is in plain air, from the fog the game set up (FogRenderer and the fog environments).
// In air, the sky fog ends at the render distance (capped at 512 blocks), before the environmental fog does.
// In water and under darkness, it ends with the environmental fog; under blindness, at 0.8 times it.
bool sky_in_air(SkyBus b) {
    return abs(b.fogSkyEnd - min(b.fogRenderDistanceEnd, 512.0)) < 1.0 && b.fogSkyEnd < b.fogEnvironmentalEnd - 1.0;
}

#endif

