// The glow is a fixed fan of 18 vertices (SkyRenderer): the center at (0, 100, 0), then a ring at
// (120 sin a, 120 cos a, -40 cos a). Debug shapes, the other users of this program, don't match it.
bool isSunriseFan() {
    if (ProjMat[2][3] == 0.0 || gl_VertexIndex >= 18) {
        return false;
    }
    if (gl_VertexIndex == 0) {
        return distance(Position, vec3(0.0, 100.0, 0.0)) < 0.01;
    }
    return abs(length(Position.xy) - 120.0) < 0.01 && abs(Position.z + Position.y / 3.0) < 0.01;
}

void main() {
    gl_Position = ProjMat * ModelViewMat * vec4(Position, 1.0);
    if (isSunriseFan()) {
        gl_Position = vec4(2.0, 2.0, 0.0, 1.0);   // outside the screen: nothing drawn
    }

layout(location = 0) in vec2 texCoord0;
layout(location = 1) flat in int isSun;
layout(location = 2) in float busRow;
layout(location = 3) flat in vec4 sunData;

void main() {
    // The celestial pipeline blends additively: RGB fixed point, alpha 1, on rows the sky cleared to black.
    if (isSun == 1) {
        int k = int(floor(busRow)) - SKY_ROW_SUN;
        fragColor = sky_pack_signed(sunData[clamp(k, 0, 3)]);
        return;
    }
    SKY_PROTECT_BUS

layout(location = 0) out vec2 texCoord0;
layout(location = 1) flat out int isSun;
layout(location = 2) out float busRow;
layout(location = 3) flat out vec4 sunData;

texCoord0 = UV0;

// The sun and the moon both use this program. The sun quad is scaled by 30, the moon's by 20.
isSun = abs(length(ModelViewMat[0].xyz) - 30.0) < 1.0 ? 1 : 0;
busRow = 0.0;
// Direction of the sun's center, in view space (the quad is centered on its local origin), and the rain
// brightness, which the game passes as the alpha of ColorModulator (1: clear, 0: full rain).
sunData = vec4(normalize((ModelViewMat * vec4(0.0, 0.0, 0.0, 1.0)).xyz), ColorModulator.a * 2.0 - 1.0);
if (isSun == 1) {
    int k = gl_VertexIndex % 4;
    vec2 corner = vec2(k == 1 || k == 2 ? 1.0 : 0.0, k == 2 || k == 3 ? 1.0 : 0.0);
    gl_Position = sky_strip_corner(corner, SKY_ROW_SUN, SKY_SUN_ROWS, ScreenSize);
    busRow = float(SKY_ROW_SUN) + corner.y * float(SKY_SUN_ROWS);
}

int row = int(floor(busRow));
