} else if (row < SKY_ROW_SKY) {
    int k = row - SKY_ROW_VIEW;
    fragColor = sky_pack_float(ModelViewMat[k / 4][k % 4]);
} else if (row == SKY_ROW_SKY) {
    fragColor = vec4(ColorModulator.rgb, 1.0);
} else if (row == SKY_ROW_FOG) {
    fragColor = vec4(FogColor.rgb, 1.0);
} else if (row < SKY_SKY_ROWS) {
    int k = row - SKY_ROW_FOG_PARAMS;
